import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3003';

interface Recommendation {
    BagID: string;
    BloodType: string;
    ExpiryDate: string;
    opportunityCost: number;
}

interface CrossmatchManagementProps {
    requestId: number;
    onClose: () => void;
}

const CrossmatchManagement: React.FC<CrossmatchManagementProps> = ({ requestId, onClose }) => {
    const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
    const [reservedBagId, setReservedBagId] = useState<string | null>(null);
    const [isAllocated, setIsAllocated] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchRecommendations = async () => {
            try {
                setLoading(true);
                const response = await axios.get(`${API_URL}/requests/${requestId}/recommendations`);
                setRecommendations(response.data);
                setError(null);
            } catch (err) {
                setError('Failed to fetch recommendations.');
                console.error(err);
            } finally {
                setLoading(false);
            }
        };

        fetchRecommendations();
    }, [requestId]);

    const handleReserve = async (bagId: string) => {
        try {
            await axios.post(`${API_URL}/requests/${requestId}/reserve`, { bagId });
            setReservedBagId(bagId);
            setError(null);
        } catch (err) {
            setError('Failed to reserve bag.');
            console.error(err);
        }
    };

    const handleAllocate = async () => {
        if (!reservedBagId) return;
        try {
            await axios.post(`${API_URL}/requests/${requestId}/allocate`, { bagId: reservedBagId });
            setIsAllocated(true);
            setError(null);
            alert('Bag successfully allocated!');
            onClose(); // Close the view after allocation
        } catch (err) {
            setError('Failed to allocate bag.');
            console.error(err);
        }
    };

    if (loading) return <div>Loading recommendations...</div>;
    if (error) return <div className="alert error">{error}</div>;

    return (
        <div className="crossmatch-management">
            <h3>Manage Crossmatch for Request #{requestId}</h3>
            <button onClick={onClose} className="button button-close">Close</button>
            
            {!reservedBagId ? (
                <table>
                    <thead>
                        <tr>
                            <th>Bag ID</th>
                            <th>Blood Type</th>
                            <th>Expiry Date</th>
                            <th>Status</th>
                            <th>Opportunity Cost</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        {recommendations.map((rec) => (
                            <tr key={rec.BagID}>
                                <td>{rec.BagID}</td>
                                <td>{rec.BloodType}</td>
                                <td>{new Date(rec.ExpiryDate).toLocaleDateString()}</td>
                                <td>{new Date(rec.ExpiryDate) < new Date() ? 'Expired' : 'Available'}</td>
                                <td>{rec.opportunityCost.toFixed(4)}</td>
                                <td>
                                    <button onClick={() => handleReserve(rec.BagID)} className="button">
                                        Reserve for Crossmatch
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            ) : (
                <div>
                    <p>Bag <strong>{reservedBagId}</strong> is reserved.</p>
                    {!isAllocated && (
                        <button onClick={handleAllocate} className="button button-primary">
                            Allocate Bag
                        </button>
                    )}
                </div>
            )}
        </div>
    );
};

export default CrossmatchManagement;
